    private val byId = all.associateBy { it.id }

    fun byId(id: String?): OsIcon? = id?.let { byId[it] }

    /**
     * Skrip deteksi OS (POSIX sh, dikirim lewat stdin ke `sh -s`). Read-only dan cepat. Di Windows,
     * `sh` tidak ada sehingga stderr berisi "not recognized" — itu yang menandai Windows.
     */
    val DETECT_SCRIPT = """
        uname -s 2>/dev/null | sed 's/^/uname=/'
        uname -o 2>/dev/null | sed 's/^/unameo=/'
        if [ -r /etc/os-release ]; then sed -n 's/^ID=/id=/p; s/^ID_LIKE=/like=/p; s/^PRETTY_NAME=/pretty=/p' /etc/os-release; fi
        if [ -r /proc/device-tree/model ]; then echo "model=${'$'}(tr -d '\000' < /proc/device-tree/model)"; fi
        command -v pveversion >/dev/null 2>&1 && echo pve=1
        [ -f /etc.defaults/VERSION ] && echo synology=1
        command -v midclt >/dev/null 2>&1 && echo truenas=1
        if [ "${'$'}(uname -s 2>/dev/null)" = Darwin ]; then echo "pretty=macOS ${'$'}(sw_vers -productVersion 2>/dev/null)"; fi
        exit 0
    """.trimIndent()

    data class Detected(val id: String, val name: String)

    /** Tentukan OS dari keluaran [DETECT_SCRIPT]. */
    fun parse(stdout: String, stderr: String = ""): Detected? {
        val kv = HashMap<String, String>()
        for (raw in stdout.lineSequence()) {
            val line = raw.trim()
            val eq = line.indexOf('=')
            if (eq <= 0) continue
            kv[line.substring(0, eq)] = line.substring(eq + 1).trim().trim('"', '\'')
        }
        if (kv.isEmpty()) {
            val all = (stdout + "\n" + stderr).lowercase()
            return if ("not recognized" in all || "windows" in all) Detected("windows", "Windows") else null
        }
        val uname = kv["uname"].orEmpty()
        val pretty = kv["pretty"].orEmpty()
        val id = kv["id"].orEmpty().lowercase()
        val like = kv["like"].orEmpty().lowercase().split(' ').filter { it.isNotBlank() }
        val model = kv["model"].orEmpty()

        fun d(osId: String, fallback: String) = Detected(osId, pretty.ifBlank { fallback })

        when {
            uname.equals("Darwin", true) -> return d("macos", "macOS")
            uname.contains("FreeBSD", true) -> return d("freebsd", "FreeBSD")
            kv["unameo"].orEmpty().equals("Android", true) -> return d("android", "Android")
            uname.contains("MINGW", true) || uname.contains("MSYS", true) || uname.contains("CYGWIN", true) ->
                return d("windows", "Windows")
            kv["pve"] == "1" -> return d("proxmox", "Proxmox VE")
            kv["synology"] == "1" -> return d("synology", "Synology DSM")
            kv["truenas"] == "1" -> return d("truenas", "TrueNAS")
            model.contains("Raspberry Pi", true) || id == "raspbian" -> return d("raspberrypi", model.ifBlank { "Raspberry Pi OS" })
        }
        val direct = mapOf(
            "ubuntu" to "ubuntu", "debian" to "debian", "arch" to "archlinux", "archarm" to "archlinux",
            "fedora" to "fedora", "centos" to "centos", "rhel" to "redhat", "rocky" to "rockylinux",
            "almalinux" to "almalinux", "alpine" to "alpinelinux", "linuxmint" to "linuxmint",
            "opensuse" to "opensuse", "opensuse-leap" to "opensuse", "opensuse-tumbleweed" to "opensuse",
            "sles" to "opensuse", "manjaro" to "manjaro", "manjaro-arm" to "manjaro", "kali" to "kalilinux",
            "gentoo" to "gentoo", "nixos" to "nixos", "pop" to "popos", "elementary" to "elementary",
            "deepin" to "deepin", "zorin" to "zorin", "endeavouros" to "endeavouros", "openwrt" to "openwrt",
            "freebsd" to "freebsd",
        )
        direct[id]?.let { return d(it, id) }
        // Turunan yang tidak dikenal: pakai keluarga induknya (ID_LIKE), mis. "ubuntu debian".
        for (l in like) direct[l]?.let { return d(it, l) }
        if (uname.equals("Linux", true) || id.isNotBlank()) return d("linux", "Linux")
        return null
    }
}
